export default function FrancisXavier({ p, detail }: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* The sea. */}
        <path {...p('water')} d={SEA_MASK} fillRule="evenodd" />

        {/* The island, its palms and the foreground planting. */}
        <path {...p('garden')} d={LAND_MASK} fillRule="evenodd" />

        {/* The caravel. */}
        <path {...p('symbol')} d={SHIP_MASK} fillRule="evenodd" />

        {/* Halo disc behind the head. */}
        <path {...p('halo')} d={HALO_MASK} fillRule="evenodd" />

        {/* The outer robe. */}
        <path {...p('mantle')} d={MANTLE_MASK} fillRule="evenodd" />

        {/* The cassock and its button placket. */}
        <path {...p('robe')} d={CASSOCK_MASK} fillRule="evenodd" />

        {/* The clerical collar and the cuffs. */}
        <path {...p('innerCollar')} d={COLLAR_MASK} fillRule="evenodd" />

        {/* The crucifix, the INRI titulus and the cincture. */}
        <path {...p('accent')} d={CROSS_MASK} fillRule="evenodd" />

        {/* The gilt corpus on the crucifix. */}
        <path {...p('emblem')} d={CORPUS_MASK} fillRule="evenodd" />

        {/* The book. */}
        <path {...p('book')} d={BOOK_MASK} fillRule="evenodd" />

        {/* Hair and beard. */}
        <path {...p('hair')} d={HAIR_MASK} fillRule="evenodd" />

        {/* Face, ear and both hands. */}
        <path {...p('skin')} d={SKIN_MASK} fillRule="evenodd" />

        {/* Exact traced black line art; deliberately non-interactive. */}
        <path
          {...detail}
          {...ink}
          d={FRANCIS_XAVIER_LINE_ART}
          fillRule="evenodd"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}
